Local Ltac fast_eassumption :=
  first [ lazymatch goal with
          | |- rw_cells _ _ ?A _ => match goal with H : rw_cells _ _ A _ |- _ => exact H end
          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ _ ?A _ => match goal with H : bytes_at _ _ A _ |- _ => exact H end
          | |- u8arr _ _ ?A _ => match goal with H : u8arr _ _ A _ |- _ => exact H end
          end
        | eassumption ].
Local Ltac fast_assumption :=
  lazymatch goal with
  | |- ?G => tryif has_evar G then assumption else
             first [ lazymatch G with
                     | rw_cells _ _ ?A _ => match goal with H : rw_cells _ _ A _ |- _ => exact H end
                     | ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
                     | bytes_at _ _ ?A _ => match goal with H : bytes_at _ _ A _ |- _ => exact H end
                     | u8arr _ _ ?A _ => match goal with H : u8arr _ _ A _ |- _ => exact H end
                     end
                   | assumption ]
  end.
(* [comment removed for export] *)
Local Ltac notrap ::=
  let K := fresh "KT" in
  step; if_cases K; zify_cond K;
  [ exfalso;
    first [ rewrite land7_mod8 in K; first [ match goal with H : _ |- _ => exact (K H) end | lia ]
          | lia
          | rewrite land3_mod4 in K; first [ match goal with H : _ |- _ => exact (K H) end | lia ]
          | rewrite lxor_m1_64 in K by lia; lia
          | rewrite land6_of_mod8 in K by lia; lia
          | rewrite land4_of_mod8 in K by lia; lia
          | let t := type of K in fail 100 "notrap: cannot refute the trap condition" t ]
  | clear K ].

