Definition prep_frame (m : mem) (spq : Z) (j64 : list byte) (w64 w72 : word) (j80 : list byte)
    (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) : Prop :=
  rw_cells usegs m spq [CB 64 j64; C8 w64; C8 w72; CB 8 j80; C8 s9v; C8 s8v; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav].

(* [comment removed for export] *)
Lemma prep_frame_fold : forall m A (ja : list byte) (u v : word) (jb : list byte) (w64 w72 w80 : word) rest,
  rw_cells usegs m A (CB 40 ja :: C8 u :: C8 v :: CB 8 jb :: C8 w64 :: C8 w72 :: C8 w80 :: rest) ->
  rw_cells usegs m A (CB 64 (ja ++ le8 u ++ le8 v ++ jb) :: C8 w64 :: C8 w72 :: CB 8 (le8 w80) :: rest).
Proof.
  intros m A ja u v jb w64 w72 w80 rest H. pose proof H as [[WF _] _]. cbn in WF. destruct WF as (La & _ & _ & Lb & _ & _ & _ & WR).
  eapply rw_cells_reshape; [exact H| |].
  - cbn. rewrite !length_app. cbn. repeat split; try lia. exact WR.
  - cbn [cells_bytes cbytes]. rewrite <- !app_assoc. reflexivity.
Qed.

Lemma prep_frame_fold1 : forall m A (ja : list byte) (u : word) (jb : list byte) rest,
  rw_cells usegs m A (CB 40 ja :: C8 u :: CB 16 jb :: rest) -> rw_cells usegs m A (CB 64 (ja ++ le8 u ++ jb) :: rest).
Proof.
  intros m A ja u jb rest H. pose proof H as [[WF _] _]. cbn in WF. destruct WF as (La & _ & Lb & WR).
  eapply rw_cells_reshape; [exact H| |].
  - cbn. rewrite !length_app. cbn. repeat split; try lia. exact WR.
  - cbn [cells_bytes cbytes]. rewrite <- !app_assoc. reflexivity.
Qed.

