Ltac deref_sides :=
  try lazymatch goal with
    | |- evt _ _ _ => idtac
    | |- stk _ _ _ _ => rewrite unsigned_lit by lia; fast_eassumption
    | |- mem_inv _ _ => fast_eassumption
    | |- _ mod 8 = 0 => fast_assumption
    | |- _ = _ -> _ => intros ?E; first [lia | exfalso; unfold hidden in *; congruence]
    | |- _ \/ _ => rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add length]; first [right; lia | left; lia]
    | |- _ => rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add length]; lia
    end.
