(* [comment removed for export] *)
(* [comment removed for export] *)
Definition prep_attail_post (spq : Z) (gp tp s10 s11 : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
    (F : bvmap 5 word) (fc : bv 32) (res b : Z) (es : list mbe) (insz n x lo : Z) (W : list (Z * Z)) (m : mem) : machine_state -> Prop :=
  fun ms' => exists rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 t3 t4 t5 t6 m' j64 j80,
    ms' = MS (mkR rax (wz spq) gp tp t0 t1 t2 (wz n) (wz res) a0 a1 a2 a3 a4 a5 a6 a7 (wz b) (wz (b + 8)) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_PREP_TAIL) fc None m' (seg_rom usegs)
    /\ munch W m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo spq
    /\ prep_frame m' spq j64 (wz (spq + 64)) (wz (spq + 64)) j80 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav
    /\ MBmid m' b es insz n x.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition PREP_SEGN_STACK : Z := 192.   (* [comment removed for export] *)

Definition prep_segN_stmt : Prop := forall (res b : Z) (es : list mbe) (insz n x lo : Z)
    (ra sp : word) gp tp (t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem),
  MBuf m b es insz -> mb_need es insz n = false -> 1 <= n -> insz + n <= 2^30 ->
  stk usegs m lo (bv_unsigned sp) -> lo + PREP_SEGN_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= b -> bv_unsigned sp mod 16 = 0 ->
  mem_inv usegs m ->
  evt usegs (prep_attail_post (bv_unsigned sp - 176) gp tp s10 s11 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra F fc res b es insz n x lo
               [(lo, bv_unsigned sp); (b + 24, b + 64)]%Z m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz b) (wz n) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_MB_PREPARE) fc None m (seg_rom usegs)).

